        nx, ny = sx + dx, sy + dy
        if blocked(nx, ny):
            continue
        rsd = best_res_dist(nx, ny)
        ods = abs(nx - ox) + abs(ny - oy)
        on_res = 1 if (nx, ny) in res else 0
        score = -rsd + 0.15 * ods + 5 * on_res
        cand.append((score, nx, ny, dx, dy))

