            nx, ny = sx + dx, sy + dy
            if inb(nx, ny) and (nx, ny) not in obst:
                return [dx, dy]
        return [0, 0]

    cand.sort(key=lambda t: (-t[0], t[1], t[2], t[3], t[4]))
    return [cand[0][3], cand[0][4]]

